\begin{lemma}[Conformality of the weak minimum]
\label{lem:annular-disk-conformal}
\uses{lem:annular-disk-minimum,lem:annular-energy-competitor}
\lean{PoincareMT.m65WeakDisk_conformal_of_normalized_minimum}
The minimum $u$ is weakly conformal: its two weak derivative
columns have equal metric norm and are orthogonal almost everywhere.
\end{lemma}
\begin{proof}
Write their Gram coefficients as $a,b,c$ and $e_0=(a+c)/2$.
A compactly supported Beltrami variation with parameter $t\nu$
gives the exact energy
\[
 \int_{\mathbb D}
 \frac{(1+t^2|\nu|^2)e_0
       -t\{\operatorname{Re}\nu(a-c)+2\operatorname{Im}\nu\,b\}}
      {1-t^2|\nu|^2}.
\]
Its derivative at zero vanishes by minimality and dominated
convergence. Real and imaginary test functions yield $a=c$ and
$b=0$. No differentiable dependence of the chosen coordinate
maps on the variation parameter is required.
\end{proof}

